"""Data model for inventory items."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


def validate_quantity(quantity: Any) -> int:
    """Return ``quantity`` if it is a positive integer, else raise ValueError."""
    # bool is a subclass of int, but True/False are not meaningful quantities.
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise ValueError(f"quantity must be an integer, got {quantity!r}")
    if quantity < 1:
        raise ValueError(f"quantity must be at least 1, got {quantity}")
    return quantity


@dataclass
class Item:
    """A named item with a positive quantity.

    Names are stripped of surrounding whitespace. Two items refer to the same
    thing when their ``key`` (case-folded name) matches.
    """

    name: str
    quantity: int = 1

    def __post_init__(self) -> None:
        if not isinstance(self.name, str) or not self.name.strip():
            raise ValueError("item name must be a non-empty string")
        self.name = self.name.strip()
        self.quantity = validate_quantity(self.quantity)

    @property
    def key(self) -> str:
        return self.name.casefold()

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "quantity": self.quantity}

    @classmethod
    def from_dict(cls, data: Any) -> Item:
        if not isinstance(data, dict):
            raise ValueError(f"item must be an object, got {type(data).__name__}")
        if "name" not in data:
            raise ValueError("item is missing required field 'name'")
        return cls(name=data["name"], quantity=data.get("quantity", 1))

import pytest

from inventory.models import Item, validate_quantity


def test_item_defaults_to_quantity_one():
    assert Item("apple").quantity == 1


def test_item_strips_name_whitespace():
    assert Item("  apple  ", 2).name == "apple"


@pytest.mark.parametrize("name", ["", "   ", None, 42])
def test_item_rejects_invalid_name(name):
    with pytest.raises(ValueError, match="name"):
        Item(name)


@pytest.mark.parametrize("quantity", [0, -3, 1.5, "2", True])
def test_item_rejects_invalid_quantity(quantity):
    with pytest.raises(ValueError, match="quantity"):
        Item("apple", quantity)


def test_validate_quantity_returns_valid_value():
    assert validate_quantity(7) == 7


def test_key_is_case_insensitive():
    assert Item("Apple").key == Item("APPLE").key == "apple"


def test_to_dict_from_dict_round_trip():
    item = Item("Widget", 4)
    assert Item.from_dict(item.to_dict()) == item


def test_from_dict_defaults_missing_quantity():
    assert Item.from_dict({"name": "pear"}) == Item("pear", 1)


def test_from_dict_requires_name():
    with pytest.raises(ValueError, match="'name'"):
        Item.from_dict({"quantity": 3})


@pytest.mark.parametrize("data", [["apple", 1], "apple", None])
def test_from_dict_rejects_non_object(data):
    with pytest.raises(ValueError, match="object"):
        Item.from_dict(data)

"""Reading and writing the inventory JSON file.

The file holds a single object: ``{"items": [{"name": ..., "quantity": ...}]}``.
"""

from __future__ import annotations

import json
import os
import tempfile
from collections.abc import Iterable
from pathlib import Path

from inventory.models import Item


class StorageError(Exception):
    """The inventory file could not be read, parsed or written."""


def load_items(path: str | os.PathLike[str]) -> list[Item]:
    """Return the items stored at ``path``; a missing file means no items."""
    path = Path(path)
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return []
    except OSError as exc:
        raise StorageError(f"cannot read {path}: {exc.strerror or exc}") from exc

    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise StorageError(f"{path} is not valid JSON: {exc.msg}") from exc

    if not isinstance(data, dict) or not isinstance(data.get("items"), list):
        raise StorageError(f"{path} must contain an object with an 'items' list")

    items = []
    for index, entry in enumerate(data["items"]):
        try:
            items.append(Item.from_dict(entry))
        except ValueError as exc:
            raise StorageError(f"{path}: item {index} is invalid: {exc}") from exc
    return items


def save_items(path: str | os.PathLike[str], items: Iterable[Item]) -> None:
    """Write ``items`` to ``path`` atomically, creating parent directories."""
    path = Path(path)
    payload = {"items": [item.to_dict() for item in items]}
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        # Write to a sibling temp file and rename it into place, so a crash
        # mid-write never leaves a truncated inventory behind.
        fd, tmp_name = tempfile.mkstemp(
            dir=path.parent, prefix=f".{path.name}.", suffix=".tmp"
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                json.dump(payload, handle, indent=2, ensure_ascii=False)
                handle.write("\n")
            os.replace(tmp_name, path)
        except BaseException:
            os.unlink(tmp_name)
            raise
    except OSError as exc:
        raise StorageError(f"cannot write {path}: {exc.strerror or exc}") from exc
